:root {
  --bg: oklch(97% 0.02 95);
  --surface: oklch(99% 0.01 95);
  --surface-2: oklch(94% 0.03 95);
  --text: oklch(28% 0.03 70);
  --muted: oklch(48% 0.03 80);
  --brand: oklch(55% 0.12 155);
  --brand-dark: oklch(44% 0.1 155);
  --accent: oklch(68% 0.09 65);
  --coffee: oklch(40% 0.05 55);
  --shadow: 0 12px 28px color-mix(in oklab, black 10%, transparent);
  --radius: 18px;
  --maxw: 1160px;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  color: var(--text);
  background: linear-gradient(180deg, var(--bg), oklch(96% 0.02 80));
}
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
.container { width: min(var(--maxw), 92vw); margin: 0 auto; }
.header {
  position: sticky; top: 0; z-index: 20;
  background: color-mix(in oklab, var(--surface) 88%, transparent);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid color-mix(in oklab, var(--muted) 20%, white);
}
.nav { display: flex; align-items: center; justify-content: space-between; height: 74px; }
.brand { display: flex; align-items: center; gap: .7rem; font-weight: 800; }
.bean {
  width: 34px; height: 34px; border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, var(--accent), var(--coffee));
  box-shadow: inset 0 0 0 2px color-mix(in oklab, white 55%, transparent);
}
.nav-links { display: flex; gap: 1.2rem; align-items: center; }
.nav-links a { font-weight: 600; color: var(--muted); }
.nav-links a.active, .nav-links a:hover { color: var(--brand-dark); }
.btn {
  border: none; border-radius: 999px; padding: .72rem 1.1rem; font-weight: 700;
  cursor: pointer; transition: .2s ease;
}
.btn-primary { background: var(--brand); color: white; }
.btn-primary:hover { background: var(--brand-dark); }
.btn-ghost { background: var(--surface-2); color: var(--text); }
.hero {
  display: grid; grid-template-columns: 1.1fr .9fr; gap: 2rem;
  align-items: center; padding: 3rem 0;
}
.card {
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border: 1px solid color-mix(in oklab, var(--muted) 20%, white);
}
.hero-copy h1, h1, h2, h3, h4 {
  font-family: 'DM Sans', Inter, sans-serif;
  letter-spacing: -.02em;
}
.hero-copy h1 { font-size: clamp(2rem, 5vw, 3.4rem); margin: 0 0 .8rem; }
.hero-copy p { color: var(--muted); font-size: 1.06rem; line-height: 1.6; }
.row { display: flex; gap: .8rem; flex-wrap: wrap; }
.hero-img {
  min-height: 360px; border-radius: var(--radius);
  background: linear-gradient(135deg, oklch(80% 0.06 85), oklch(62% 0.1 65));
  position: relative; overflow: hidden;
}
.hero-img::before {
  content: ""; position: absolute; inset: 14% 12%; border-radius: 50%;
  background: radial-gradient(circle at 40% 35%, oklch(94% 0.02 80), oklch(70% 0.07 65));
  box-shadow: 0 20px 40px color-mix(in oklab, black 12%, transparent);
}
.hero-caption {
  position: absolute; left: 1rem; bottom: 1rem; background: color-mix(in oklab, white 75%, transparent);
  padding: .65rem .9rem; border-radius: 999px; font-size: .85rem; font-weight: 700;
}
.section { padding: 1.6rem 0 2.6rem; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
.feature { padding: 1rem; }
.feature .placeholder {
  height: 160px; border-radius: 14px; margin-bottom: .8rem;
  background: linear-gradient(140deg, oklch(88% 0.05 120), oklch(74% 0.08 75));
}
.meta { color: var(--muted); font-size: .95rem; }
.footer { background: oklch(92% 0.02 95); border-top: 1px solid color-mix(in oklab, var(--muted) 25%, white); padding: 2rem 0; }
.footer-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }
.footer h4 { margin: 0 0 .8rem; font-size: 1rem; }
.footer ul { margin: 0; padding: 0; list-style: none; display: grid; gap: .45rem; color: var(--muted); }
.cookie {
  position: fixed; left: 50%; transform: translateX(-50%); bottom: 1rem;
  width: min(900px, 94vw); padding: .9rem; display: flex; gap: .8rem; align-items: center; justify-content: space-between;
}
.page-title { padding: 2rem 0 1rem; }
.layout { display: grid; grid-template-columns: 260px 1fr; gap: 1.2rem; }
.sidebar { padding: 1rem; position: sticky; top: 90px; height: fit-content; }
.sidebar ul { list-style: none; padding: 0; margin: 0; display: grid; gap: .45rem; }
.sidebar a { display: block; padding: .55rem .7rem; border-radius: 10px; color: var(--muted); font-weight: 600; }
.sidebar a:hover { background: var(--surface-2); color: var(--brand-dark); }
.menu-block { padding: 1rem; margin-bottom: 1rem; }
.menu-items { display: grid; grid-template-columns: repeat(2, 1fr); gap: .8rem; }
.item { padding: .8rem; border-radius: 12px; background: var(--surface-2); }
.tabs { display: flex; gap: .5rem; flex-wrap: wrap; margin-bottom: 1rem; }
.tab { padding: .55rem .8rem; border-radius: 999px; border: 1px solid color-mix(in oklab, var(--muted) 35%, white); background: white; font-weight: 700; cursor: pointer; }
.tab.active { background: var(--brand); color: white; border-color: var(--brand); }
.tier-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: .9rem; margin: 1rem 0 1.4rem; }
.tier { padding: 1rem; }
.carousel { padding: 1rem; }
.track { display: grid; grid-auto-flow: column; grid-auto-columns: calc((100% - 1rem) / 2); gap: 1rem; overflow: hidden; scroll-behavior: smooth; }
.gift-card { min-height: 170px; border-radius: 16px; padding: 1rem; color: white; font-weight: 700; display: flex; align-items: end; }
.nav-arrows { display: flex; gap: .5rem; justify-content: end; margin-bottom: .8rem; }
.arrow { width: 40px; height: 40px; border-radius: 50%; border: none; background: var(--surface-2); cursor: pointer; font-size: 1.2rem; }
.store-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
.map { min-height: 430px; padding: 1rem; background: linear-gradient(160deg, oklch(92% 0.03 210), oklch(80% 0.05 185)); position: relative; }
.pin { width: 14px; height: 14px; border-radius: 50%; background: var(--brand-dark); position: absolute; box-shadow: 0 0 0 6px color-mix(in oklab, var(--brand) 25%, transparent); }
.search-box { padding: 1rem; }
.input { width: 100%; padding: .72rem .85rem; border-radius: 10px; border: 1px solid color-mix(in oklab, var(--muted) 35%, white); }
.suggestions { margin-top: .6rem; display: none; border: 1px solid color-mix(in oklab, var(--muted) 30%, white); border-radius: 10px; overflow: hidden; }
.suggestions button { width: 100%; text-align: left; padding: .6rem .8rem; border: none; background: white; cursor: pointer; }
.suggestions button:hover { background: var(--surface-2); }
.toggle { display: inline-flex; background: var(--surface-2); border-radius: 999px; padding: .2rem; gap: .2rem; }
.toggle button { border: none; padding: .45rem .8rem; border-radius: 999px; font-weight: 700; background: transparent; cursor: pointer; }
.toggle button.active { background: var(--brand); color: white; }
.filter-panel { display: none; margin-top: .7rem; padding: .75rem; border-radius: 12px; background: var(--surface-2); }
@media (max-width: 900px) {
  .hero, .store-grid, .layout, .grid-3, .tier-grid, .footer-grid, .menu-items { grid-template-columns: 1fr; }
  .nav-links { gap: .7rem; font-size: .95rem; }
  .track { grid-auto-columns: 100%; }
}
@media (max-width: 700px) {
  .footer-col ul { display: none; }
  .footer-col.open ul { display: grid; }
  .footer-col h4 { cursor: pointer; padding: .55rem 0; border-bottom: 1px solid color-mix(in oklab, var(--muted) 25%, white); }
}
EOF

cat > /app/output/script.js <<'EOF'
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];

const page = document.body.dataset.page;

if (page === 'home') {
  const cookie = $('#cookieBanner');
  $('#cookieAgree')?.addEventListener('click', () => cookie?.remove());

  if (window.matchMedia('(max-width: 700px)').matches) {
    $$('.footer-col h4').forEach(h => {
      h.addEventListener('click', () => h.parentElement.classList.toggle('open'));
    });
  }
}

if (page === 'rewards') {
  const tabs = $$('.tab');
  const panel = $('#redemptionPanel');
  const content = {
    25: 'Customize your drink with an extra espresso shot, dairy alternative, or flavored syrup.',
    60: 'Enjoy a bakery favorite: butter croissant, cake pop, or warm cookie.',
    100: 'Redeem a handcrafted beverage, hot breakfast item, or parfait.',
    200: 'Pick a lunch sandwich, protein box, or packaged coffee to take home.',
    300: 'Take home whole bean coffee, merchandise, or premium drinkware.',
    400: 'Celebrate big with select at-home brewing gear and signature bundles.'
  };
  tabs.forEach(t => t.addEventListener('click', () => {
    tabs.forEach(x => x.classList.remove('active'));
    t.classList.add('active');
    panel.textContent = content[t.dataset.stars];
  }));
}

const setupCarousel = (rootId) => {
  const root = document.getElementById(rootId);
  if (!root) return;
  const track = $('.track', root);
  $('.prev', root).addEventListener('click', () => {
    track.scrollBy({ left: -track.clientWidth, behavior: 'smooth' });
  });
  $('.next', root).addEventListener('click', () => {
    track.scrollBy({ left: track.clientWidth, behavior: 'smooth' });
  });
};
setupCarousel('featuredCarousel');
['Birthday','Thank You','Celebration','Appreciation','Encouragement','Workplace'].forEach(c => setupCarousel('cat-' + c.replace(/\s+/g, '-')));

if (page === 'store-locator') {
  const suggestions = $('#suggestions');
  const input = $('#storeSearch');
  const mapTitle = $('#mapTitle');
  const results = $('#results');
  const data = ['Seattle, WA','Portland, OR','San Francisco, CA','Austin, TX','Chicago, IL'];

  input.addEventListener('input', () => {
    const q = input.value.trim().toLowerCase();
    const list = data.filter(x => x.toLowerCase().includes(q));
    suggestions.innerHTML = list.map(v => `<button type="button">${v}</button>`).join('');
    suggestions.style.display = q ? 'block' : 'none';
    if (q) {
      mapTitle.textContent = `Showing nearby stores for “${input.value}”`;
      results.textContent = `${Math.max(2, list.length)} stores available`;
    }
    $$('button', suggestions).forEach(btn => btn.addEventListener('click', () => {
      input.value = btn.textContent;
      suggestions.style.display = 'none';
      mapTitle.textContent = `Showing nearby stores for “${btn.textContent}”`;
      results.textContent = `4 stores available`;
    }));
  });

  $('#filterBtn').addEventListener('click', () => {
    const panel = $('#filterPanel');
    panel.style.display = panel.style.display === 'block' ? 'none' : 'block';
  });

  $$('#orderType button').forEach(btn => {
    btn.addEventListener('click', () => {
      $$('#orderType button').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      results.textContent = btn.dataset.type === 'pickup' ? '6 pickup-ready stores' : '3 delivery-enabled stores';
    });
  });
}
EOF

